<div class="stats"><div class="stat"><span>Active Users</span><b><?=$counts['users']?></b><small>Approved accounts</small></div><div class="stat"><span>Pending Signups</span><b><?=$counts['requests']?></b><small>Admin approval required</small></div><div class="stat"><span>Roles</span><b><?=$counts['roles']?></b><small>Role presets</small></div><div class="stat"><span>Modules</span><b><?=$counts['modules']?></b><small>Assignable modules</small></div></div><div class="grid2"><section class="panel"><div class="panel-head"><div><h2>Users</h2><p>Create and assign access</p></div><div class="spacer"></div><button class="btn primary" data-open="userModal">+ New User</button></div><div class="panel-body"><div class="table-wrap"><table class="table"><thead><tr><th>Name</th><th>Login</th><th>Admin</th><th>Status</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><b><?=e($u['full_name'])?></b></td><td><?=e($u['email'])?><br><small><?=e($u['username'])?></small></td><td><?=$u['is_tenant_admin']?'<span class="tag green">Admin</span>':'—'?></td><td><span class="tag green"><?=e($u['status'])?></span></td></tr><?php endforeach;?></tbody></table></div></div></section><section class="panel"><div class="panel-head"><div><h2>Pending Signup Requests</h2></div></div><div class="panel-body"><?php if(!$requests):?><div class="flash ok">No pending signup requests.</div><?php endif;?><?php foreach($requests as $r):?><div style="border:1px solid var(--line);padding:9px;margin-bottom:7px;border-radius:7px"><b style="font-size:11px"><?=e($r['full_name'])?></b><div style="font-size:9px;color:var(--muted);margin:3px 0"><?=e($r['email'])?> · <?=e($r['phone'])?></div><form method="post" action="/?r=user-approve" style="margin-top:7px"><?=csrf_field()?><input type="hidden" name="request_id" value="<?=e($r['id'])?>"><div style="display:flex;gap:5px;align-items:center;flex-wrap:wrap"><select name="role_id" style="max-width:180px"><?php foreach($roles as $role):?><option value="<?=$role['id']?>"><?=e($role['name'])?></option><?php endforeach;?></select><button class="btn primary">Approve & Activate</button></div><details style="margin-top:6px"><summary style="font-size:9px;color:#087b50;cursor:pointer">Customize assigned modules</summary><div style="display:grid;grid-template-columns:repeat(2,1fr);gap:4px;margin-top:6px"><?php foreach($modules as $m):?><label style="border:1px solid var(--line);padding:5px;font-size:9px"><input type="checkbox" name="modules[]" value="<?=$m['id']?>" style="width:auto;height:auto"> <?=e($m['name'])?></label><?php endforeach;?></div></details></form></div><?php endforeach;?></div></section></div><div class="modal" id="userModal"><div class="dialog"><div class="dialog-head"><div><h3>Create User</h3><p>Role + module assignment</p></div><button type="button" class="close" data-close>×</button></div><form method="post" action="/?r=user-create"><div class="dialog-body"><?=csrf_field()?><div class="form-grid"><label><span>Full Name</span><input name="full_name" required></label><label><span>Email</span><input name="email" type="email" required></label><label><span>Username</span><input name="username"></label><label><span>Phone</span><input name="phone"></label><label><span>Temporary Password</span><input name="password" value="ChangeMe123!" required></label><label><span>Role</span><select name="role_id"><?php foreach($roles as $role):?><option value="<?=$role['id']?>"><?=e($role['name'])?></option><?php endforeach;?></select></label></div><div style="font-size:11px;font-weight:650;margin:12px 0 6px">Assigned Modules</div><div class="module-cards"><?php foreach($modules as $m):?><label class="module-card" style="min-height:auto"><input type="checkbox" name="modules[]" value="<?=$m['id']?>" style="width:auto;height:auto"> <b><?=e($m['name'])?></b><p><?=e($m['module_key'])?></p></label><?php endforeach;?></div><label style="display:flex;gap:5px;align-items:center;margin-top:10px"><input type="checkbox" name="is_admin" value="1" style="width:auto;height:auto"> Tenant Admin</label></div><div class="dialog-foot"><button class="btn" type="button" data-close>Cancel</button><button class="btn primary">Create User</button></div></form></div></div>